import pandas as pd, numpy as np
train = pd.read_csv('train.csv'); test = pd.read_csv('test.csv')
fc = [c for c in train.columns if c != 'target']
Xtr = train[fc].values; y = train['target'].values; Xte = test[fc].values; yt = test['target'].values

def gnb_pred(Xtr, y, Xte):
    classes = np.unique(y); n = len(y)
    pr={}; mu={}; v={}
    for c in classes:
        m = y==c; pr[c]=m.sum()/n; mu[c]=Xtr[m].mean(0); v[c]=Xtr[m].var(0)+1e-6
    lp = np.zeros((len(Xte),len(classes)))
    for ci,c in enumerate(classes):
        for i in range(len(Xte)):
            lp[i,ci] = np.log(pr[c]) - 0.5*np.sum(np.log(2*np.pi*v[c]) + (Xte[i]-mu[c])**2/v[c])
    return np.argmax(lp,1)

for ss in [3,5,7,10,15,20,30,50]:
    rng = np.random.RandomState(42)
    votes = np.zeros((len(Xte),2))
    for _ in range(300):
        idx = rng.choice(50,size=min(ss,50),replace=False)
        p = gnb_pred(Xtr[:,idx],y,Xte[:,idx])
        for i in range(len(Xte)): votes[i,p[i]]+=1
    fp = np.argmax(votes,1)
    print(f'ss={ss}: acc={(fp==yt).mean():.3f} dist={np.bincount(fp,minlength=2)}')
"

