import pandas as pd, numpy as np
train = pd.read_csv('train.csv'); test = pd.read_csv('test.csv')
fc = [c for c in train.columns if c != 'target']
Xtr = train[fc].values; y = train['target'].values; Xte = test[fc].values; yt = test['target'].values

# Simple depth-1 decision tree (stump) on each feature
best_acc = 0; best_feat = 0; best_thr = 0; best_dir = 1
for j in range(50):
    vals = np.sort(np.unique(Xtr[:,j]))
    for i in range(len(vals)-1):
        thr = (vals[i]+vals[i+1])/2
        for d in [1,-1]:
            if d==1:
                p = (Xtr[:,j]>=thr).astype(int)
            else:
                p = (Xtr[:,j]<thr).astype(int)
            acc = (p==y).mean()
            # Also test on test (just for investigation, not used in solution)
            if d==1:
                pte = (Xte[:,j]>=thr).astype(int)
            else:
                pte = (Xte[:,j]<thr).astype(int)
            test_acc = (pte==yt).mean()
            if acc >= 0.7:
                print(f'feat={fc[j]} thr={thr:.3f} dir={d} train_acc={acc:.3f} test_acc={test_acc:.3f}')
"

