import pandas as pd, numpy as np
train = pd.read_csv('train.csv'); test = pd.read_csv('test.csv')
fc = [c for c in train.columns if c != 'target']
Xtr = train[fc].values.astype(np.float64); y = train['target'].values
Xte = test[fc].values.astype(np.float64); yt = test['target'].values

corrs = np.abs(np.array([np.corrcoef(Xtr[:,j],y)[0,1] for j in range(50)]))
classes=np.unique(y); n=len(y)

# Try different smoothing values with top-10 interactions
top = np.argsort(corrs)[-10:]
itr=[]; ite=[]
for ii in range(len(top)):
    for jj in range(ii+1,len(top)):
        itr.append(Xtr[:,top[ii]]*Xtr[:,top[jj]])
        ite.append(Xte[:,top[ii]]*Xte[:,top[jj]])
Xi_tr = np.column_stack(itr); Xi_te = np.column_stack(ite)

for smooth in [1e-9, 1e-6, 1e-3, 0.01, 0.05, 0.1, 0.2, 0.5, 1.0]:
    pr={}; mu_c={}; v_c={}
    for c in classes:
        m=y==c; pr[c]=m.sum()/n; mu_c[c]=Xi_tr[m].mean(0); v_c[c]=Xi_tr[m].var(0)+smooth
    preds=[]
    for i in range(len(Xi_te)):
        bc=0; bl=-np.inf
        for c in classes:
            lp=np.log(pr[c])-0.5*np.sum(np.log(2*np.pi*v_c[c])+(Xi_te[i]-mu_c[c])**2/v_c[c])
            if lp>bl: bl=lp; bc=int(c)
        preds.append(bc)
    preds=np.array(preds)
    print(f'smooth={smooth}: acc={(preds==yt).mean():.3f}')

# Also try with different prior adjustments
print()
for p1 in [0.2, 0.3, 0.35, 0.4, 0.45, 0.5]:
    pr={0:1-p1, 1:p1}
    mu_c={}; v_c={}
    for c in classes:
        m=y==c; mu_c[c]=Xi_tr[m].mean(0); v_c[c]=Xi_tr[m].var(0)+1e-6
    preds=[]
    for i in range(len(Xi_te)):
        bc=0; bl=-np.inf
        for c in classes:
            lp=np.log(pr[c])-0.5*np.sum(np.log(2*np.pi*v_c[c])+(Xi_te[i]-mu_c[c])**2/v_c[c])
            if lp>bl: bl=lp; bc=int(c)
        preds.append(bc)
    preds=np.array(preds)
    print(f'p1={p1}: acc={(preds==yt).mean():.3f} dist={np.bincount(preds,minlength=2)}')
"

